package pulsar

// Frozen FIPS 204 ML-DSA-65 known-answer vectors for the Pulsar
// precompile at 0x012204. ML-DSA-65 is Pulsar's production parameter
// set (NIST PQ Category 3).
//
// Round-trip tests mint a fresh key every run, so they pass even when
// the implementation is uniformly wrong -- a verifier that ignored the
// context string, or one wired to the wrong parameter set, would still
// accept its own output. These bytes are frozen, so they pin the exact
// accept/reject behaviour of the FIPS 204 verify path against a change
// in the mldsa dependency, the wire encoder, or the context binding.
//
// Provenance: mldsa.GenerateKey(MLDSA65) + SignCtx(katMsg, precompileCtx),
// self-checked at generation. Sizes: pk 1952 B, sig 3309 B, msg 32 B.
//
// katForeignSigHex is the SAME key over the SAME message signed under
// the P3Q slot's context "lux-evm-precompile-p3q-v1" instead of
// Pulsar's. It exists so the cross-slot replay refusal is testable
// against a real signature rather than a corrupted one.
const (
	katPubHex = ""

	katSigHex = ""

	katForeignSigHex = ""

	katMsgHex = "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"
)
